* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; font-family: 'Poppins', 'Helvetica Neue', Arial, sans-serif; }

.topbar {
  height: 100%;
  width: 100%;
  display: flex;
  align-items: center;
  background: #fff;
  padding: 0 26px;
  overflow: hidden;
}

.topbar__title-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.topbar__title {
  font-size: 17px;
  font-weight: 700;
  color: #1D2751;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.topbar__sub {
  font-size: 12px;
  color: #4A5568;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

