/* Header (Custom Widget) — franja superior fija con título/subtítulo
 * dinámico según el tab activo del TABS_WIDGET "mainScreen" (appsmith.store.selTab).
 * Replica pageTitle/pageSubtitle (derived stores) de router.ts del dashboard
 * Svelte original: cada ruta ahí tiene su propio título + subtítulo (código
 * MB-FOR, descripción corta, etc.) — aquí cada tabName cumple el mismo rol
 * que cada Route.name. */

const TEXTOS = {
  BandejaTareas: {
    titulo: "Bandeja de tareas",
    subtitulo: "Tareas de intervención humana asignadas a tu rol",
  },
  Procesos: {
    titulo: "Procesos",
    subtitulo: "Procesos habilitados — selecciona uno para instanciar",
  },
  PerfilCliente: {
    titulo: "Perfil del Cliente",
    subtitulo: "MB-FOR-23-013 · Perfil del Cliente Persona Natural",
  },
};

function render(model) {
  const tabName = model && model.activeTab;
  const textos = TEXTOS[tabName] || { titulo: "", subtitulo: "" };

  const titulo = document.getElementById("hd-titulo");
  const subtitulo = document.getElementById("hd-subtitulo");
  if (titulo) titulo.textContent = textos.titulo;
  if (subtitulo) subtitulo.textContent = textos.subtitulo;
}

appsmith.onReady(() => {
  render(appsmith.model);
  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange((m) => render(m));
  }
});

